/* ==========================================================================
   STRINGS — Übersetzungstexte DE/EN/PL für data-i18n* (siehe t()/
   applyTranslations() in app.js). AP-D (ARCHITEKTUR-PLAN.md): mechanisch
   trivial auszulagern, aber semantisch an das data-i18n-Markup in index.html
   gekoppelt — deshalb vorher der Schlüsselparitäts-Selbsttest in
   runSelfTests() (DE/EN/PL exakt dieselben Schlüssel). Verwaiste Schlüssel
   einmalig vor der Auslagerung statisch geprüft (Markup + t()-Aufrufstellen
   in app.js, inklusive der wenigen mit zusammengesetztem statt wörtlichem
   Schlüssel) — keine gefunden.

   t() und applyTranslations() bleiben in app.js: beide hängen an settings
   bzw. am DOM und sind damit kein Blatt. Dieses Modul ist reine Daten, ohne
   jede Logik.
   ========================================================================== */

