    'settings.about.privacy': 'Deine Songs, Aufnahmen, Notizen und Einstellungen bleiben auf diesem Gerät — die App sendet keine Inhalte. Beim Öffnen fragt der Browser bei GitHub Pages (wo die App liegt) nach einer neuen Version; dabei sieht GitHub wie bei jedem Webseitenaufruf IP-Adresse und Zeitpunkt, aber keine Inhalte. Nur auf deinen Tipp hin: Die Liedsuche (Lupe im Player) schickt Songtitel und ggf. Interpret an den gewählten Dienst (Tidal, Spotify, Deezer, YouTube oder Google; bei YouTube und Google zusätzlich das Wort „Musik“), und der Zeitabgleich der Lichtshow fragt die Atomuhr der PTB (uhr.ptb.de) nach der Uhrzeit.',
    'settings.about.librariesTitle': 'Lizenzen / Danke',
    'settings.about.thanksIntro': 'Die Klänge und einige Bausteine dieser App stammen von anderen – danke! Werk, Urheber, Quelle und Lizenz:',
    'settings.about.fluidr3': 'Bass, Streicher, Gitarre, Chor und Bläser: <strong>FluidR3 GM</strong> von Frank Wen, als Einzeltöne von Benjamin Gleitzman (<a href="https://github.com/gleitz/midi-js-soundfonts" target="_blank" rel="noopener noreferrer">midi-js-soundfonts</a>) — Lizenz <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>; für die App gekürzt und neu kodiert.',
    'settings.about.salamander': 'Klavier: <strong>Salamander Grand Piano</strong> (Yamaha C5) von Alexander Holm, in der Fassung von <a href="https://github.com/Tonejs/audio" target="_blank" rel="noopener noreferrer">Tone.js</a> — Lizenz <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>; in der App gekürzt, zu Mono gemischt und gleichstufig umgestimmt.',
    'settings.about.vcsl': 'Schlagzeug: <strong>Versilian Community Sample Library</strong> von Versilian Studios (<a href="https://github.com/sgossner/VCSL" target="_blank" rel="noopener noreferrer">github.com/sgossner/VCSL</a>) — <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a> (gemeinfrei); gekürzt und neu kodiert.',
    'settings.about.lame': 'MP3-Export: <strong>lamejs</strong> (JavaScript-Portierung von zhuker, <a href="https://github.com/zhuker/lamejs" target="_blank" rel="noopener noreferrer">github.com/zhuker/lamejs</a>) auf Basis von <strong>LAME</strong> (<a href="https://lame.sourceforge.net/" target="_blank" rel="noopener noreferrer">lame.sourceforge.net</a>) — <a href="https://github.com/bokajsukriz/choirapp/blob/main/LICENSE-lamejs-LGPL-3.0.txt" target="_blank" rel="noopener noreferrer">LGPL-3.0</a>.',
    'settings.about.stretch': 'Verlangsamung im Modus „HD“: <strong>signalsmith-stretch</strong> von Geraint Luff / Signalsmith Audio Ltd. (<a href="https://signalsmith-audio.co.uk/code/stretch/" target="_blank" rel="noopener noreferrer">signalsmith-audio.co.uk</a>) — <a href="https://github.com/bokajsukriz/choirapp/blob/main/LICENSE-signalsmith-stretch.txt" target="_blank" rel="noopener noreferrer">MIT</a>.',
    'settings.about.licenses': 'Alle Lizenztexte, Herkunft und Änderungen: <a href="https://github.com/bokajsukriz/choirapp/blob/main/THIRD-PARTY.md" target="_blank" rel="noopener noreferrer">THIRD-PARTY.md</a> und <a href="https://github.com/bokajsukriz/choirapp/blob/main/samples/LIZENZ.md" target="_blank" rel="noopener noreferrer">samples/LIZENZ.md</a>.',
