    'lab.melody': 'Melodie',
    'lab.melodyOn': 'Melodie spielen',
    'lab.melodyHint': 'Die Melodien folgen Tonart und Akkordfolge (Reiter Harmonie) und passen deshalb immer zum Bass. „Bearbeiten“ öffnet den Editor: Tippen setzt einen Ton, weiterziehen macht ihn länger, Tippen auf einen Ton löscht ihn. Die Zahlen links sind Stufen über dem gerade klingenden Akkord – 1 ist sein Grundton, 1, 3 und 5 (rosa) sind Akkordtöne. 1–7 gibt es dreimal: in der Mitte, darüber („höher“) und darunter („tiefer“). Zum Blättern die Leiste mit den Zahlen ziehen. So wandert deine Melodie mit der Akkordfolge mit. Mit „Zwischentöne“ kannst du bewusst Töne außerhalb der Tonart setzen: ♭ und ♯ liegen einen Halbton neben der Stufe und erscheinen lila. „Als eigene speichern“ legt die Melodie unter „Eigene“ ab. „Oktave“ legt die Lage fest.',
