    'lab.autoEmpty': 'Keine Reglerbewegung aufgenommen.',
    'lab.autoHint': 'Nimmt deine Reglerbewegungen im Klang-Reiter auf und spielt sie im Takt immer wieder ab – z. B. ein Filter, der sich über zwei Takte öffnet. Takte wählen, „Bewegung aufnehmen“ tippen: Nach einem Takt Einzählen wird jede Änderung an den Reglern (auch den vier großen) mitgeschrieben. Helligkeit/Cutoff und Resonanz wirken sofort auch auf klingende Töne, die übrigen Regler ab dem nächsten Ton. Mit dem Schalter lässt sich die Automation pausieren.',
    'lab.recLoopPlay': 'Aufnahme im Loop abspielen',
    'lab.recLoopPause': 'Loop anhalten',
    'lab.recHint': 'Wähle, wie viele Takte du aufnehmen willst, und tippe „Aufnehmen“. Der Groove startet (falls er noch nicht läuft), zählt einen Takt ein, und dann wird alles aufgezeichnet, was du auf der Klaviatur oder den Tonart-Tasten spielst – genau so, wie du es spielst, ohne Raster. Nach den gewählten Takten endet die Aufnahme von selbst und läuft gleich als Loop weiter (Play/Pause rechts unten auf der Rolle). „Als Melodie speichern“ legt sie unter Melodie → „Eigene“ ab; dort kannst du sie wie jede Melodie bearbeiten. Die Melodie ist nur einstimmig: Spielst du Töne gleichzeitig, endet der vorige beim nächsten Anschlag.',
