    'lab.keysLayoutAria': 'Tastenansicht',
    'lab.helpBass': 'Der Klang der Basslinie im Loop. Welche Töne sie spielt, bestimmen Tonart und Akkordfolge im Reiter Harmonie.',
    'lab.helpGroove': 'Swing verschiebt jede zweite Sechzehntel etwas nach hinten, das klingt lässiger und „rollender“. Pumpen macht die Synths bei jedem Kick kurz leiser und lässt sie dann wieder anschwellen, typisch für House und Pop.',
    'lab.helpKey': 'Grundton und Modus legen fest, aus welchen Tönen Melodie, Bass, Arpeggiator und Akkorde schöpfen. Dur klingt hell, Moll dunkler. Dorisch ist Moll mit hellerer Sexte (jazzig), Mixolydisch ist Dur mit kleiner Septime (rockig).',
    'lab.helpProgression': 'Die Akkordfolge wechselt jeden oder jeden zweiten Takt. Die römischen Zahlen zeigen die Stufe in der Tonart: große Zahlen sind Dur-Akkorde, kleine Moll-Akkorde, ° ist vermindert. Ein Tipp auf die Folge öffnet die Auswahl mit Pop, Klassik, Jazz und Modal & Folk – von zwei bis zwölf Akkorden, jeweils mit kurzer Erklärung. „Bearbeiten“: Akkord in der Leiste antippen und darunter austauschen; + fügt dahinter einen ein, − entfernt ihn, die Pfeile verschieben. „Als eigene speichern“ legt die Folge unter „Eigene“ ab.',
    'lab.catPop': 'Pop',
    'lab.catClassic': 'Klassik',
    'lab.catJazz': 'Jazz',
    'lab.catModal': 'Modal & Folk',
