    'lab.progNameJazz': 'Zwei-Fünf-Eins',
    'lab.progNameTwoFiveOne': 'Zwei-Fünf-Eins (kurz)',
    'lab.progNameTurnaround': 'Turnaround',
    'lab.progNameChain': 'Quintfall-Kette',
    'lab.progNameModal': 'Mixolydisch',
    'lab.progNameRock3': 'Rock-Dreier',
    'lab.progNameAndalusian': 'Andalusische Kadenz',
    'lab.progNameEpic': 'Epische Moll-Folge',
    'lab.progNameDrone': 'Nur Grundakkord',
    'lab.progInfoPop': 'Die Folge hinter unzähligen Pop-Hits: Grundakkord, Dominante, Moll-Parallele, Subdominante – eingängig und hell.',
    'lab.progInfoSad': 'Dieselben vier Akkorde, aber in Moll begonnen – klingt nachdenklich und sehnsüchtig.',
    'lab.progInfoFifties': 'Der Klang der 50er-Balladen („Stand by Me“): warm, rund, ein wenig nostalgisch.',
    'lab.progInfoRoyal': 'Beliebt im J-Pop: beginnt auf der Subdominante und schwebt, ohne richtig anzukommen.',
    'lab.progInfoPendulum': 'Nur zwei Akkorde im Wechsel – viel Platz für Melodie und Improvisation, gut für Gospel und zum Einsingen.',
    'lab.progInfoBlues': 'Die Grundform des Blues über zwölf Akkorde: viermal I, zweimal IV, zweimal I, dann V – IV – I – I.',
    'lab.progInfoCadence': 'Tonika – Subdominante – Dominante – Tonika: die Kadenz der Klassik und Kirchenmusik, schließt eindeutig – in Moll mit Dur-Dominante (Leitton).',
    'lab.progInfoCadence3': 'I–IV–V: endet auf der Dominante, einem Halbschluss – erst der nächste Durchlauf löst zur Tonika auf.',
    'lab.progInfoAmen': 'Die plagale Wendung wie beim „Amen“ am Ende eines Chorals – sanft statt zwingend. Drei Akkorde.',
    'lab.progInfoPlagal': 'Tonika und Subdominante im Wechsel – ruhig und hymnisch.',
    'lab.progInfoPachelbel': 'Die Folge aus Pachelbels Kanon: acht Akkorde, deren Grundtöne abwechselnd eine Quarte fallen und eine Sekunde steigen – darüber sinkt die Oberstimme Ton für Ton. Auch in vielen Popsongs.',
    'lab.progInfoCircle': 'Barocke Sequenz über acht Akkorde: jeder Grundton liegt eine Quinte unter dem vorigen, das zieht unaufhaltsam zur Tonika.',
    'lab.progInfoJazz': 'Die wichtigste Wendung im Jazz, mit Septakkorden – der letzte Takt ruht auf der Tonika.',
    'lab.progInfoTwoFiveOne': 'Dieselbe Wendung in drei Akkorden – und gleich wieder von vorn.',
    'lab.progInfoTurnaround': 'Die Jazz-Schleife am Ende eines Chorus: führt immer zurück zum Anfang.',
    'lab.progInfoChain': 'Vier Septakkorde im Quintfall – jazzig und immer in Bewegung, erst der nächste Durchlauf löst auf.',
    'lab.progInfoModal': 'Rock- und Folk-Klang mit der Stufe ♭VII – nur in Mixolydisch, Dorisch oder Moll.',
    'lab.progInfoRock3': 'Drei Akkorde wie in vielen Rocksongs – nur in Mixolydisch, Dorisch oder Moll.',
    'lab.progInfoAndalusian': 'Absteigende Flamenco-Folge – nur in Moll, sie endet auf der Dur-Dominante.',
    'lab.progInfoEpic': 'Filmmusik-Klang: groß, dunkel und weit – nur in Moll.',
    'lab.progInfoDrone': 'Ein einziger Akkord – ideal zum Einsingen und für Übungen über dem Grundton.',
    'lab.helpSound': 'Presets sind fertige Klänge für Melodie, Arpeggiator und Tasten. Die vier Regler darunter verändern das Wichtigste mit einem Griff. Unter „Mehr Einstellungen“ gibt es jeden Parameter einzeln. Die Chor-Akkorde klingen immer nach Chor.',
    'lab.helpEffects': 'Hall macht einen Raum, Echo wiederholt die Töne im Tempo, Chorus macht den Klang breiter und schwebend. „Anteil“ bestimmt, wie viel vom Synth in den Effekt geht; Länge, Feedback und Echo-Zeit stellen den Effekt selbst ein.',
    'lab.helpMixer': 'Lautstärke je Spur: auf den Balken tippen oder ziehen. Der Lautsprecher links schaltet eine Spur stumm. „Gesamt“ regelt alles zusammen.',
    'lab.helpArp': 'Ein Arpeggiator spielt Töne nacheinander statt gleichzeitig, im Tempo des Grooves. Ohne „Automatisch“ spielst du selbst: Halte Tasten gedrückt, und das Muster bestimmt, was daraus wird – „Nach Auswahl“ spielt genau deine Töne, „Terzen“, „Quinten“ oder „Dreiklänge“ bauen auf jedem Ton passend zur Tonart auf. Mit „Halten“ tippst du Tasten nacheinander an; sie bleiben, bis du sie noch einmal antippst oder löschst. Mit „Automatisch“ folgt der Arp der Akkordfolge, solange der Groove läuft. „Spielreihenfolge“ spielt die Töne so, wie du sie gedrückt hast. Punktierte Tempi (1/8 ·) laufen gegen den Takt und klingen wie ein Echo; „punktiert“ im Rhythmus gibt einen hüpfenden Shuffle.',
    'lab.helpOsc': 'Die Grundwellenform: Sinus klingt weich und rund, Dreieck flötig, Rechteck hohl wie eine Klarinette, Sägezahn hell und scharf wie Streicher oder Bläser.',
    'lab.helpEnv': 'Die Hüllkurve formt die Lautstärke jedes Tons: Attack ist das Einschwingen, Decay das Abfallen danach, Sustain der Pegel, solange der Ton gehalten wird, Release das Ausklingen nach dem Loslassen.',
    'lab.helpFilter': 'Der Filter nimmt Obertöne weg: Tiefpass macht dunkler, Hochpass dünner, Bandpass nasal. Cutoff ist die Grenzfrequenz, Resonanz betont sie, Env→Filter öffnet den Filter beim Anschlag, Drive zerrt leicht an.',
    'lab.helpLfo': 'Ein LFO ist eine sehr langsame Schwingung, die hier den Filter bewegt: von leichtem Wabern bis zum „Wobble“-Bass. „Im Takt“ koppelt die Geschwindigkeit an das Tempo.',
    'lab.helpCharacter': 'Detune und Breite machen den Klang voller: mehrere leicht verstimmte Stimmen, links und rechts verteilt. Sub-Level fügt eine Oktave tiefer hinzu, Pitch-Drop lässt jeden Ton von oben einrutschen.',
    'lab.helpVibrato': 'Vibrato ist eine leichte, regelmäßige Tonhöhenschwankung wie bei Sänger:innen. Rate ist die Geschwindigkeit, Tiefe die Stärke, Einsatz die Verzögerung, bis es beginnt.',
    'lab.helpGlide': 'Glide lässt die Tonhöhe von einem Ton zum nächsten gleiten, statt zu springen. Mono spielt immer nur einen Ton gleichzeitig, typisch für Lead-Synths und Bässe.',
    'lab.tabMixer': 'Mixer',
