    // <<< Groove Lab Redesign
    'lab.viewStudio': 'Studio',
    'lab.choirTask': 'Aufgabe',
    'lab.choirHelp': 'Wähle eine Aufgabe: Sie stellt Groove, Akkordfolge, Tempo und Stimmen passend ein. Alles lässt sich danach frei ändern — und mit ↶ zurücknehmen. Im Studio gibt es alle Klang-, Mixer- und Keys-Einstellungen.',
    'lab.choirPick': 'Wähle eine Aufgabe',
    'lab.choirPickHint': 'Jede Aufgabe übt etwas, das in der Chorprobe gebraucht wird — mit Begleitung zum Mitsingen.',
    'lab.choirPartAsk': 'Welche Stimme singst du?',
    'lab.choirNow': 'Jetzt',
    'lab.choirNoBeat': 'Kein Beat',
    'lab.choirProg': 'Akkordfolge',
    'lab.choirYou': 'du',
    'lab.choirRoot': 'Grundton',
    'lab.choirThird': 'Terz',
    'lab.choirSing': 'Singe',
    'lab.choirListen': 'Hören',
    'lab.choirYouSing': 'Du',
    'lab.choirClap24': 'Klatschen auf 2 und 4',
    'lab.choirBeatFade': 'Beat ausblenden',
    'lab.choirBeatBack': 'Beat zurück',
    'lab.melodyAltBars': 'Melodie jeden 2. Takt (Echo)',
    'lab.task.meineStimme.title': 'Singe deine Stimme mit',
    'lab.task.meineStimme.help1': 'Der vierstimmige Satz klingt, deine Stimme ist hervorgehoben. Sing sie mit — erst mit, dann versuch, sie allein zu halten.',
    'lab.task.meineStimme.help2': 'Tipp: Tempo langsam, dann steigern.',
    'lab.task.minusEins.title': 'Deine Stimme fehlt',
    'lab.task.minusEins.help1': 'Die anderen drei Stimmen klingen, deine ist stumm. Füll die Lücke.',
    'lab.task.minusEins.help2': 'Wenn du unsicher wirst: kurz auf „Singe deine Stimme mit“ wechseln und zurück.',
    'lab.task.bass.title': 'Singe die Grundtöne',
    'lab.task.bass.help1': 'Sing zu jedem Akkord seinen Grundton — das ist das Fundament, auf dem der Chor stimmt.',
    'lab.task.bass.help2': 'Tiefe Stimmen in ihrer Lage, hohe eine Oktave höher.',
    'lab.task.terzen.title': 'Singe die Terz',
    'lab.task.terzen.help1': 'Sing zu jedem Akkord seine Terz. Die Anzeige nennt sie dir.',
    'lab.task.terzen.help2': 'Die Terz entscheidet über Dur und Moll — und wird im Chor am leichtesten zu tief.',
    'lab.task.liegeton.title': 'Tonleiter zum Liegeton',
    'lab.task.liegeton.help1': 'Nur der Grundton mit Quinte klingt. Sing langsam die Tonleiter hinauf und hinunter und hör, wie jeder Ton zum Liegeton steht.',
    'lab.task.liegeton.help2': 'Bei 3 und 7 genau hinhören: Die große Terz eher knapp, der Leitton hoch genug.',
    'lab.task.pentatonik.title': 'Improvisieren mit fünf Tönen',
    'lab.task.pentatonik.help1': 'Erfinde kurze Melodien nur aus den fünf angezeigten Tönen — mit ihnen kann nichts schief klingen.',
    'lab.task.pentatonik.help2': 'Erst ein Ton, dann zwei, dann kleine Motive. Pausen sind erlaubt und gut.',
    'lab.task.echo.title': 'Echo',
    'lab.task.echo.help1': 'Die App singt einen Takt vor, im nächsten Takt singst du ihn nach.',
    'lab.task.echo.help2': 'Erst genau nachsingen, später leicht verändern — so entsteht Frage und Antwort.',
    'lab.task.zweiVier.title': 'Klatschen auf 2 und 4',
    'lab.task.zweiVier.help1': 'Wie im Gospel: auf 2 und 4 klatschen, auf 1 und 3 mit dem Fuß.',
    'lab.task.zweiVier.help2': 'Die Anzeige blinkt auf 2 und 4. Erst im Sitzen, dann im Stehen mit Schritt zur Seite.',
    'lab.task.swing.title': 'Swing-Achtel',
    'lab.task.swing.help1': 'Sprich zum Beat „du-ba du-ba“: das „du“ lang, das „ba“ kurz und spät — wie „lang-kurz“.',
    'lab.task.swing.help2': 'Dann dieselbe Achtelbewegung auf einem Ton singen.',
    'lab.task.beatbox.title': 'Mundschlagzeug',
    'lab.task.beatbox.help1': 'Mach den Beat mit dem Mund mit: „bm“ für die Bassdrum, „ka“ für die Snare, „ts“ für die Hi-Hat.',
    'lab.task.beatbox.help2': 'Wenn es sitzt: „Beat ausblenden“ — dann trägst du den Groove allein.',
    // Groove Lab: Workshop (ARBEITSANWEISUNG-WORKSHOP.md)
