    'settings.screen.hint': 'Keeps the screen from dimming while a song is open. Only prevents automatic dimming from inactivity — doesn\'t help if you lock the phone yourself with the power button.',
    'settings.screen.bgHelpToggle': 'Background playback not working?',
    'settings.screen.bgHelpIntro': 'If playback stops as soon as you lock your phone, that\'s not this app\'s fault: Android decides whether a web app may keep running in the background, controlled by two system settings — both can only be changed by hand, no website can set them itself.',
    'settings.screen.step1': 'Android settings → <strong>Apps</strong> → open your browser (e.g. <strong>Vanadium</strong> or <strong>Chrome</strong> — the app you used "Add to home screen" with).',
    'settings.screen.step2': '<strong>Battery</strong> → choose <strong>Unrestricted</strong>. Otherwise Android shuts the browser down in the background as soon as the screen turns off.',
    'settings.screen.step3': '<strong>Notifications</strong> → allow. Android requires a visible notification for this — without it, no web app may keep playing in the background.',
    'settings.screen.grapheneNote': 'Without Google Play services — e.g. on GrapheneOS — "Add to home screen" usually only creates a shortcut, not a proper app icon with its own permissions. Both settings then apply to the browser itself, not a separate "BVG" icon.',
    'settings.screen.notifyBtn': 'Allow notifications for this page',

