    'settings.about.title': 'About the app',
    'settings.about.version': 'Version',
    'settings.about.offline': 'Available offline',
    'settings.about.upToDate': "You're already on the latest version.",
    'settings.about.checkUpdateFailed': 'Checking for a newer version failed.',
    'settings.about.checkUpdateUnsupported': "This browser can't check for updates manually.",
    'settings.about.forceUpdate': 'update now',
    'settings.about.rebuildOffline': 'reload offline copy',
    'settings.about.rebuildOfflineTitle': 'Reload the offline copy?',
    'settings.about.rebuildOfflineText': 'The stored app version is discarded and loaded fresh from the internet. Songs, recordings, notes and settings are kept. Only do this while online.',
    'settings.about.forcingUpdate': 'Looking for a newer version — will load it right away if found …',
    'settings.about.forceUpdateApplying': 'Found a newer version, loading it …',
    'settings.about.privacy': 'Your songs, recordings, notes and settings stay on this device — the app sends no content. When opened, the browser asks GitHub Pages (where the app is hosted) for a new version; like any website visit, GitHub sees your IP address and the time, but no content. Only when you tap it: the song search (magnifying glass in the player) sends the song title, and artist if known, to the chosen service (Tidal, Spotify, Deezer, YouTube or Google; for YouTube and Google also the word “Musik”), and the light show time sync asks PTB’s atomic clock (uhr.ptb.de) for the time.',
    'settings.about.librariesTitle': 'Licenses / Thanks',
    'settings.about.thanksIntro': 'The sounds and some building blocks of this app come from others — thank you! Work, author, source and license:',
    'settings.about.fluidr3': 'Bass, strings, guitar, choir and brass: <strong>FluidR3 GM</strong> by Frank Wen, as single notes by Benjamin Gleitzman (<a href="https://github.com/gleitz/midi-js-soundfonts" target="_blank" rel="noopener noreferrer">midi-js-soundfonts</a>) — license <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>; trimmed and re-encoded for the app.',
    'settings.about.salamander': 'Piano: <strong>Salamander Grand Piano</strong> (Yamaha C5) by Alexander Holm, in the <a href="https://github.com/Tonejs/audio" target="_blank" rel="noopener noreferrer">Tone.js</a> edition — license <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>; trimmed, mixed to mono and retuned to equal temperament in the app.',
    'settings.about.vcsl': 'Drums: <strong>Versilian Community Sample Library</strong> by Versilian Studios (<a href="https://github.com/sgossner/VCSL" target="_blank" rel="noopener noreferrer">github.com/sgossner/VCSL</a>) — <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a> (public domain); trimmed and re-encoded.',
    'settings.about.lame': 'MP3 export: <strong>lamejs</strong> (JavaScript port by zhuker, <a href="https://github.com/zhuker/lamejs" target="_blank" rel="noopener noreferrer">github.com/zhuker/lamejs</a>) based on <strong>LAME</strong> (<a href="https://lame.sourceforge.net/" target="_blank" rel="noopener noreferrer">lame.sourceforge.net</a>) — <a href="https://github.com/bokajsukriz/choirapp/blob/main/LICENSE-lamejs-LGPL-3.0.txt" target="_blank" rel="noopener noreferrer">LGPL-3.0</a>.',
    'settings.about.stretch': 'Slowdown in <strong>HD</strong> mode: <strong>signalsmith-stretch</strong> by Geraint Luff / Signalsmith Audio Ltd. (<a href="https://signalsmith-audio.co.uk/code/stretch/" target="_blank" rel="noopener noreferrer">signalsmith-audio.co.uk</a>) — <a href="https://github.com/bokajsukriz/choirapp/blob/main/LICENSE-signalsmith-stretch.txt" target="_blank" rel="noopener noreferrer">MIT</a>.',
    'settings.about.licenses': 'All license texts, origin and changes: <a href="https://github.com/bokajsukriz/choirapp/blob/main/THIRD-PARTY.md" target="_blank" rel="noopener noreferrer">THIRD-PARTY.md</a> and <a href="https://github.com/bokajsukriz/choirapp/blob/main/samples/LIZENZ.md" target="_blank" rel="noopener noreferrer">samples/LIZENZ.md</a>.',
