    'onb.installIosStep3': 'Tap <strong>Add</strong> in the top right — done.',
    'onb.installIosNote': 'Without this step iOS deletes the stored recordings if the app is not opened for a while.',
    'onb.installOtherStep1': 'Open the <strong>menu</strong> in the top right of the browser (⋮).',
    'onb.installOtherStep2': 'Choose <strong>“Install app”</strong> or <strong>“Add to Home screen”</strong>.',
    'onb.installOtherStep3': 'Confirm — the icon then sits next to your other apps.',
