    'lab.melodyOn': 'Play melody',
    'lab.melodyHint': 'Melodies follow the key and chord progression (Harmony tab), so they always fit the bass. “Edit” opens the editor: tap to place a note, keep dragging to make it longer, tap a note to delete it. The numbers on the left are scale steps above the chord that is playing – 1 is its root, 1, 3 and 5 (pink) are chord tones. 1–7 appear three times: in the middle, above (“higher”) and below (“lower”). Drag the number strip to scroll. That way your melody moves along with the chords. “Chromatic notes” lets you deliberately place notes outside the key: ♭ and ♯ sit a semitone next to the step and show in purple. “Save as my own” keeps the melody under “My own”. “Octave” sets the register.',
