    'lab.autoHint': 'Records your knob movements in the Sound tab and plays them back in time, over and over – e.g. a filter opening over two bars. Choose the bars and tap “Record movement”: after a one-bar count-in every change to the knobs (including the four big ones) is captured. Brightness/cutoff and resonance also affect sounding notes right away, the other knobs from the next note on. The switch pauses the automation.',
    'lab.recLoopPlay': 'Play take in a loop',
    'lab.recLoopPause': 'Pause loop',
    'lab.recHint': 'Choose how many bars to record and tap “Record”. The groove starts (if it isn’t running yet), counts in one bar, and then everything you play on the keyboard or scale pads is recorded – exactly as you play it, without a grid. Recording stops by itself after the chosen bars and keeps playing as a loop (play/pause at the bottom right of the roll). “Save as melody” keeps it under Melody → “My own”, where you can edit it like any melody. Melodies are single-voice: if you play notes together, the previous one ends at the next key press.',
