    'lab.helpBass': 'The sound of the loop’s bass line. Which notes it plays is set by the key and chord progression in the Harmony tab.',
    'lab.helpGroove': 'Swing delays every second sixteenth a little, which sounds more laid back and rolling. Pump briefly ducks the synths on every kick and lets them swell back, typical of house and pop.',
    'lab.helpKey': 'Root and mode decide which notes the melody, bass, arpeggiator and chords use. Major sounds bright, minor darker. Dorian is minor with a brighter sixth (jazzy), Mixolydian is major with a flat seventh (rocky).',
    'lab.helpProgression': 'The progression changes every bar or every two bars. Roman numerals show the scale degree: upper case is a major chord, lower case minor, ° diminished. Tap the progression to open the list with pop, classical, jazz and modal & folk – from two to twelve chords, each with a short explanation. “Edit”: tap a chord in the strip and swap it below; + adds one after it, − removes it, the arrows move it. “Save as my own” keeps the progression under “My own”.',
    'lab.catPop': 'Pop',
    'lab.catClassic': 'Classical',
    'lab.catJazz': 'Jazz',
    'lab.catModal': 'Modal & folk',
    'lab.pickProg': 'Choose progression',
    'lab.progEdit': 'Edit',
    'lab.progNew': 'New progression',
    'lab.progChordAt': 'Chord at the selected position',
    'lab.progMoveLeft': 'Move left',
    'lab.progMoveRight': 'Move right',
    'lab.progAdd': 'Chord',
    'lab.progRemove': 'Chord',
    'lab.progSevenths': 'Seventh chords',
    'lab.progDominant': 'Minor: major dominant',
    'lab.progModeSwitched': '{name} → {mode}',
    'lab.progModeMismatch': 'does not fit the mode',
    'lab.progCount': '{n} chords',
    'lab.progLibraryFull': '24 progressions of your own are already saved. Delete one first.',
    'lab.myProgN': 'My progression {n}',
    'lab.newProg': 'New progression',
    'lab.progSaved': '“{name}” saved – find it under “My own”.',
    'lab.progNamePop': 'Pop axis',
    'lab.progNameSad': 'Minor pop',
    'lab.progNameFifties': '50s / doo-wop',
    'lab.progNameRoyal': 'Royal Road',
    'lab.progNamePendulum': 'Pendulum',
    'lab.progNameBlues': '12-bar blues',
    'lab.progNameCadence': 'Basic cadence',
    'lab.progNameCadence3': 'Half-cadence loop',
    'lab.progNameAmen': 'Amen ending',
    'lab.progNamePlagal': 'Plagal swing',
    'lab.progNamePachelbel': 'Pachelbel’s Canon',
    'lab.progNameCircle': 'Circle of fifths sequence',
    'lab.progNameJazz': 'Two-five-one',
    'lab.progNameTwoFiveOne': 'Two-five-one (short)',
    'lab.progNameTurnaround': 'Turnaround',
    'lab.progNameChain': 'Chain of fifths',
    'lab.progNameModal': 'Mixolydian',
    'lab.progNameRock3': 'Rock three',
    'lab.progNameAndalusian': 'Andalusian cadence',
    'lab.progNameEpic': 'Epic minor',
    'lab.progNameDrone': 'Tonic only',
    'lab.progInfoPop': 'The progression behind countless pop hits: tonic, dominant, relative minor, subdominant – catchy and bright.',
    'lab.progInfoSad': 'The same four chords, but starting in minor – sounds thoughtful and longing.',
    'lab.progInfoFifties': 'The sound of 50s ballads (“Stand by Me”): warm, round, a little nostalgic.',
    'lab.progInfoRoyal': 'Popular in J-pop: starts on the subdominant and floats without quite landing.',
    'lab.progInfoPendulum': 'Just two chords swapping – lots of room for melody and improvisation, good for gospel and warm-ups.',
    'lab.progInfoBlues': 'The basic blues form over twelve chords: I four times, IV twice, I twice, then V – IV – I – I.',
    'lab.progInfoCadence': 'Tonic – subdominant – dominant – tonic: the cadence of classical and church music, with a clear ending – in minor with a major dominant (leading note).',
    'lab.progInfoCadence3': 'I–IV–V: ends on the dominant, a half cadence – only the next pass resolves to the tonic.',
    'lab.progInfoAmen': 'The plagal turn like the “Amen” at the end of a hymn – gentle rather than compelling. Three chords.',
    'lab.progInfoPlagal': 'Tonic and subdominant alternating – calm and hymn-like.',
    'lab.progInfoPachelbel': 'The progression from Pachelbel’s Canon: eight chords whose roots alternately fall a fourth and rise a step – above them the top voice descends step by step. Also in many pop songs.',
    'lab.progInfoCircle': 'Baroque sequence over eight chords: each root is a fifth below the last, pulling steadily towards the tonic.',
    'lab.progInfoJazz': 'The most important turn in jazz, with seventh chords – the last bar rests on the tonic.',
    'lab.progInfoTwoFiveOne': 'The same turn in three chords – and straight back to the start.',
    'lab.progInfoTurnaround': 'The jazz loop at the end of a chorus: always leads back to the start.',
    'lab.progInfoChain': 'Four seventh chords falling in fifths – jazzy and always moving, only the next round resolves.',
    'lab.progInfoModal': 'Rock and folk sound with the ♭VII chord – only in Mixolydian, Dorian or minor.',
    'lab.progInfoRock3': 'Three chords as in many rock songs – only in Mixolydian, Dorian or minor.',
    'lab.progInfoAndalusian': 'Descending flamenco progression – only in minor, ending on the major dominant.',
    'lab.progInfoEpic': 'Film-score sound: big, dark and wide – only in minor.',
    'lab.progInfoDrone': 'A single chord – ideal for warm-ups and exercises over the tonic.',
    'lab.helpSound': 'Presets are ready-made sounds for melody, arpeggiator and keys. The four knobs below change the essentials in one move; “More settings” exposes every parameter. The choir chords always sound like a choir.',
    'lab.helpEffects': 'Reverb adds a room, echo repeats notes in time, chorus makes the sound wider and shimmering. “Amount” sets how much of the synth goes into the effect; length, feedback and echo time shape the effect itself.',
    'lab.helpMixer': 'Volume per track: tap or drag the bar. The speaker on the left mutes a track. “Master” controls everything together.',
    'lab.helpArp': 'An arpeggiator plays notes one after another instead of together, in the groove’s tempo. Without “Automatic” you play it yourself: hold keys and the pattern decides what comes out – “As selected” plays exactly your notes, “Thirds”, “Fifths” or “Triads” build on each note within the key. With “Hold” you tap keys one after another; they stay until you tap them again or clear them. With “Automatic” the arp follows the chord progression while the groove runs. “Played order” plays the notes in the order you pressed them. Dotted rates (1/8 ·) run against the beat and sound like an echo; “dotted” rhythms give a bouncy shuffle.',
    'lab.helpOsc': 'The basic waveform: sine is soft and round, triangle flute-like, square hollow like a clarinet, sawtooth bright and sharp like strings or brass.',
    'lab.helpEnv': 'The envelope shapes each note’s volume: attack is the fade-in, decay the drop afterwards, sustain the level while held, release the fade-out after letting go.',
    'lab.helpFilter': 'The filter removes overtones: low-pass makes it darker, high-pass thinner, band-pass nasal. Cutoff is the edge frequency, resonance emphasises it, Env→Filter opens the filter on each note, drive adds a little grit.',
    'lab.helpLfo': 'An LFO is a very slow oscillation that moves the filter here: from a gentle wah to a wobble bass. “Tempo sync” locks its speed to the tempo.',
    'lab.helpCharacter': 'Detune and width make the sound fuller: several slightly detuned voices spread left and right. Sub level adds an octave below, pitch drop makes each note slide in from above.',
    'lab.helpVibrato': 'Vibrato is a gentle, regular pitch wobble like a singer’s. Rate is its speed, depth its strength, onset the delay before it starts.',
    'lab.helpGlide': 'Glide slides the pitch from one note to the next instead of jumping. Mono plays only one note at a time, typical of lead synths and basses.',
    'lab.tabMixer': 'Mixer',
