    'settings.screen.keepOn': 'Ekran włączony',
    'settings.screen.keepOnAria': 'Ekran włączony',
    'settings.screen.hint': 'Zapobiega przygaszaniu ekranu, dopóki utwór jest otwarty. Działa tylko przeciw automatycznemu przygaszaniu przy bezczynności — nie pomoże, gdy sam zablokujesz telefon przyciskiem.',
    'settings.screen.bgHelpToggle': 'Odtwarzanie w tle nie działa?',
    'settings.screen.bgHelpIntro': 'Jeśli odtwarzanie przerywa się zaraz po zablokowaniu telefonu, to nie wina tej aplikacji: Android decyduje, czy aplikacja webowa może działać w tle, a sterują tym dwa ustawienia systemowe — oba trzeba zmienić ręcznie, żadna strona nie może ustawić ich sama.',
    'settings.screen.step1': 'Ustawienia Androida → <strong>Aplikacje</strong> → otwórz swoją przeglądarkę (np. <strong>Vanadium</strong> lub <strong>Chrome</strong> — tę, w której użyto „Dodaj do ekranu głównego").',
    'settings.screen.step2': '<strong>Bateria</strong> → wybierz <strong>Bez ograniczeń</strong>. W przeciwnym razie Android zamknie przeglądarkę w tle, gdy tylko ekran zgaśnie.',
    'settings.screen.step3': '<strong>Powiadomienia</strong> → zezwól. Android wymaga widocznego powiadomienia — bez niego żadna aplikacja webowa nie może grać w tle.',
    'settings.screen.grapheneNote': 'Bez usług Google Play — np. na GrapheneOS — „Dodaj do ekranu głównego" zwykle tworzy tylko skrót, a nie osobną ikonę aplikacji z własnymi uprawnieniami. Oba ustawienia dotyczą wtedy samej przeglądarki, nie osobnej ikony „BVG".',
    'settings.screen.notifyBtn': 'Zezwól na powiadomienia dla tej strony',

    'settings.perf.title': 'Zwolnione odtwarzanie',
