    'settings.perf.hdUnsupported': 'To urządzenie nie obsługuje HD — Standard nadal działa.',
    'settings.perf.webkitHint': 'Safari może nadal błędnie odtwarzać zwolniony dźwięk. Dlatego HD jest tam wyłączony; można go sprawdzić przez „Spróbuj mimo to”.',
    'settings.perf.webkitForceGraph': 'Spróbuj mimo to',
