    'settings.perf.webkitForceGraphHint': 'Jeśli brzmi urywanie albo wysokość dźwięku jest błędna, błąd nie jest jeszcze naprawiony — wyłącz to ponownie.',
    'settings.perf.introTitle': 'Tryb HD',
    'settings.perf.introText': 'Tryb HD podnosi jakość dźwięku przy wolniejszym odtwarzaniu, ale na starszych telefonach może to być za dużo. Można to cofnąć w Ustawieniach. Wypróbować teraz?',
    'settings.perf.introActivate': 'Tak, wypróbuj',
