    'settings.perf.rebuildDone': 'Wyjście audio odbudowane.',
    'rec.input.narrowband': 'Mikrofon działa z jakością telefoniczną — to typowe, gdy słuchawki Bluetooth podczas nagrywania przełączają się na profil zestawu głośnomówiącego. Wtedy utwór także brzmi głucho. Pomogą słuchawki przewodowe albo wyłączenie Bluetooth.',
    'rec.input.bluetooth': 'Nagrywanie przez zestaw słuchawkowy Bluetooth. Wiele słuchawek przełącza się wtedy na jakość telefoniczną — także podczas odtwarzania. Słuchawki przewodowe brzmią znacznie lepiej.',
    'rec.input.bluetoothAfterUse': 'Android mógł pozostać w profilu głośnomówiącym Bluetooth. Rozłącz i ponownie połącz Bluetooth lub słuchawki. „Odbuduj wyjście audio” odbudowuje tylko graf Web Audio i nie może zresetować profilu Bluetooth Androida.',
    'settings.perf.advToggle': 'Ustawienia rozciągacza',
    'settings.perf.advIntro': 'Działa natychmiast, także w trakcie odtwarzania. Do eksperymentów — ustawienia domyślne są dobrane świadomie.',
