    'settings.perf.advCostHint': 'Realne oszczędności daje tylko krok albo ustawienie „Oszczędny": większy krok to mniej bloków analizy na sekundę. Długość bloku prawie nie zmienia obciążenia — decyduje o rozdzielczości i opóźnieniu.',
