    'settings.about.title': 'O aplikacji',
    'settings.about.version': 'Wersja',
    'settings.about.offline': 'Dostępna offline',
    'settings.about.upToDate': 'Masz już najnowszą wersję.',
    'settings.about.checkUpdateFailed': 'Sprawdzanie nowszej wersji nie powiodło się.',
    'settings.about.checkUpdateUnsupported': 'W tej przeglądarce nie można ręcznie sprawdzić aktualizacji.',
    'settings.about.forceUpdate': 'zaktualizuj teraz',
    'settings.about.rebuildOffline': 'wczytaj kopię offline ponownie',
    'settings.about.rebuildOfflineTitle': 'Wczytać kopię offline ponownie?',
    'settings.about.rebuildOfflineText': 'Zapisana wersja aplikacji zostanie usunięta i pobrana ponownie z internetu. Utwory, nagrania, notatki i ustawienia zostają zachowane. Wykonuj tylko z połączeniem z internetem.',
    'settings.about.forcingUpdate': 'Szukam nowszej wersji — po znalezieniu od razu ją wczytam …',
    'settings.about.forceUpdateApplying': 'Znaleziono nowszą wersję, wczytuję …',
    'settings.about.privacy': 'Twoje utwory, nagrania, notatki i ustawienia pozostają na tym urządzeniu — aplikacja nie wysyła żadnych treści. Przy otwarciu przeglądarka pyta GitHub Pages (gdzie znajduje się aplikacja) o nową wersję; jak przy każdej wizycie na stronie GitHub widzi adres IP i czas, ale żadnych treści. Tylko po Twoim dotknięciu: wyszukiwanie utworu (lupka w odtwarzaczu) wysyła tytuł i ewentualnie wykonawcę do wybranej usługi (Tidal, Spotify, Deezer, YouTube lub Google; przy YouTube i Google dodatkowo słowo „Musik”), a synchronizacja czasu pokazu świateł pyta zegar atomowy PTB (uhr.ptb.de) o godzinę.',
    'settings.about.librariesTitle': 'Licencje / Podziękowania',
    'settings.about.thanksIntro': 'Brzmienia i niektóre elementy tej aplikacji pochodzą od innych — dziękujemy! Dzieło, autor, źródło i licencja:',
    'settings.about.fluidr3': 'Bas, smyczki, gitara, chór i dęte: <strong>FluidR3 GM</strong> (autor: Frank Wen), jako pojedyncze dźwięki od Benjamina Gleitzmana (<a href="https://github.com/gleitz/midi-js-soundfonts" target="_blank" rel="noopener noreferrer">midi-js-soundfonts</a>) — licencja <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>; skrócone i ponownie zakodowane na potrzeby aplikacji.',
    'settings.about.salamander': 'Fortepian: <strong>Salamander Grand Piano</strong> (Yamaha C5; autor: Alexander Holm), w wersji <a href="https://github.com/Tonejs/audio" target="_blank" rel="noopener noreferrer">Tone.js</a> — licencja <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener noreferrer">CC BY 3.0</a>; w aplikacji skrócone, zmiksowane do mono i przestrojone na strój równomiernie temperowany.',
    'settings.about.vcsl': 'Perkusja: <strong>Versilian Community Sample Library</strong> autorstwa Versilian Studios (<a href="https://github.com/sgossner/VCSL" target="_blank" rel="noopener noreferrer">github.com/sgossner/VCSL</a>) — <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a> (domena publiczna); skrócone i ponownie zakodowane.',
    'settings.about.lame': 'Eksport MP3: <strong>lamejs</strong> (port JavaScript autorstwa zhuker, <a href="https://github.com/zhuker/lamejs" target="_blank" rel="noopener noreferrer">github.com/zhuker/lamejs</a>) oparty na <strong>LAME</strong> (<a href="https://lame.sourceforge.net/" target="_blank" rel="noopener noreferrer">lame.sourceforge.net</a>) — <a href="https://github.com/bokajsukriz/choirapp/blob/main/LICENSE-lamejs-LGPL-3.0.txt" target="_blank" rel="noopener noreferrer">LGPL-3.0</a>.',
    'settings.about.stretch': 'Spowolnienie w trybie <strong>HD</strong>: <strong>signalsmith-stretch</strong> autorstwa Geraint Luff / Signalsmith Audio Ltd. (<a href="https://signalsmith-audio.co.uk/code/stretch/" target="_blank" rel="noopener noreferrer">signalsmith-audio.co.uk</a>) — <a href="https://github.com/bokajsukriz/choirapp/blob/main/LICENSE-signalsmith-stretch.txt" target="_blank" rel="noopener noreferrer">MIT</a>.',
    'settings.about.licenses': 'Wszystkie teksty licencji, pochodzenie i zmiany: <a href="https://github.com/bokajsukriz/choirapp/blob/main/THIRD-PARTY.md" target="_blank" rel="noopener noreferrer">THIRD-PARTY.md</a> i <a href="https://github.com/bokajsukriz/choirapp/blob/main/samples/LIZENZ.md" target="_blank" rel="noopener noreferrer">samples/LIZENZ.md</a>.',
