    'lab.melodyHint': 'Melodie podążają za tonacją i progresją akordów (karta Harmonia), więc zawsze pasują do basu. „Edytuj” otwiera edytor: stuknij, aby postawić dźwięk, przeciągnij dalej, aby go wydłużyć, stuknij dźwięk, aby go usunąć. Liczby po lewej to stopnie nad aktualnie brzmiącym akordem – 1 to jego pryma, 1, 3 i 5 (różowe) to dźwięki akordu. 1–7 występują trzy razy: pośrodku, wyżej („wyżej”) i niżej („niżej”). Aby przewijać, przeciągnij pasek z liczbami. Dzięki temu melodia podąża za akordami. „Dźwięki chromatyczne” pozwalają świadomie użyć dźwięków spoza tonacji: ♭ i ♯ leżą półton obok stopnia i są fioletowe. „Zapisz jako własną” zachowuje melodię w „Własne”. „Oktawa” ustala rejestr.',
