    'lab.autoHint': 'Nagrywa ruchy gałek w karcie Brzmienie i odtwarza je w rytmie w kółko – np. filtr otwierający się przez dwa takty. Wybierz takty i stuknij „Nagraj ruch”: po jednym takcie odliczania zapisywana jest każda zmiana gałek (także czterech dużych). Jasność/cutoff i rezonans działają od razu także na brzmiące dźwięki, pozostałe gałki od następnego dźwięku. Przełącznik wstrzymuje automatykę.',
    'lab.recLoopPlay': 'Odtwarzaj nagranie w pętli',
    'lab.recLoopPause': 'Wstrzymaj pętlę',
    'lab.recHint': 'Wybierz, ile taktów chcesz nagrać, i stuknij „Nagrywaj”. Groove startuje (jeśli jeszcze nie gra), odlicza jeden takt, a potem nagrywa wszystko, co grasz na klawiaturze lub klawiszach skali – dokładnie tak, jak grasz, bez siatki. Po wybranych taktach nagrywanie kończy się samo i od razu gra dalej w pętli (odtwarzanie/pauza w prawym dolnym rogu). „Zapisz jako melodię” zachowuje je w Melodia → „Własne”, gdzie możesz je edytować jak każdą melodię. Melodie są jednogłosowe: jeśli grasz dźwięki razem, poprzedni kończy się przy następnym uderzeniu.',
