    'lab.ovl.textIdle': 'Gdy dźwięk trzeszczy lub zanika, często pomaga większy bufor. Wybierzesz go tutaj – i zobaczysz, jak obciążone jest urządzenie.',
    'lab.ovl.title': 'Urządzenie nie nadąża',
