    'lab.keysLayoutAria': 'Układ klawiszy',
    'lab.helpBass': 'Brzmienie linii basu w pętli. Jakie dźwięki gra, zależy od tonacji i progresji akordów w karcie Harmonia.',
    'lab.helpGroove': 'Swing lekko opóźnia co drugą szesnastkę, co brzmi luźniej i bardziej „tocząco”. Pompowanie przy każdym kicku na chwilę ścisza syntezatory i pozwala im znów narosnąć, typowe dla house i popu.',
    'lab.helpKey': 'Dźwięk podstawowy i tryb określają, z jakich dźwięków korzystają melodia, bas, arpeggiator i akordy. Dur brzmi jasno, moll ciemniej. Dorycka to moll z jaśniejszą sekstą (jazzowa), miksolidyjska to dur z małą septymą (rockowa).',
    'lab.helpProgression': 'Progresja zmienia się co takt lub co dwa takty. Cyfry rzymskie pokazują stopień skali: wielkie to akordy durowe, małe molowe, ° zmniejszony. Stuknij progresję, aby otworzyć listę z pop, klasyką, jazzem oraz muzyką modalną i folkiem – od dwóch do dwunastu akordów, każda z krótkim opisem. „Edytuj”: stuknij akord na pasku i wymień go poniżej; + dodaje jeden za nim, − usuwa, strzałki przesuwają. „Zapisz jako własną” zachowuje progresję w „Własne”.',
    'lab.catPop': 'Pop',
    'lab.catClassic': 'Klasyka',
