    'lab.progNameJazz': 'Dwa-pięć-jeden',
    'lab.progNameTwoFiveOne': 'Dwa-pięć-jeden (krótko)',
    'lab.progNameTurnaround': 'Turnaround',
    'lab.progNameChain': 'Łańcuch kwintowy',
    'lab.progNameModal': 'Miksolidyjska',
    'lab.progNameRock3': 'Rockowa trójka',
    'lab.progNameAndalusian': 'Kadencja andaluzyjska',
    'lab.progNameEpic': 'Epicka molowa',
    'lab.progNameDrone': 'Tylko tonika',
    'lab.progInfoPop': 'Progresja stojąca za niezliczonymi hitami: tonika, dominanta, paralela molowa, subdominanta – chwytliwa i jasna.',
    'lab.progInfoSad': 'Te same cztery akordy, ale zaczynające się od molowego – brzmi refleksyjnie i tęsknie.',
    'lab.progInfoFifties': 'Brzmienie ballad z lat 50. („Stand by Me”): ciepłe, okrągłe, nieco nostalgiczne.',
    'lab.progInfoRoyal': 'Popularna w J-popie: zaczyna od subdominanty i unosi się, nie lądując naprawdę.',
    'lab.progInfoPendulum': 'Tylko dwa akordy na zmianę – dużo miejsca na melodię i improwizację, dobre do gospel i rozśpiewania.',
    'lab.progInfoBlues': 'Podstawowa forma bluesa na dwunastu akordach: cztery razy I, dwa razy IV, dwa razy I, potem V – IV – I – I.',
    'lab.progInfoCadence': 'Tonika – subdominanta – dominanta – tonika: kadencja muzyki klasycznej i kościelnej, kończy się jednoznacznie – w molu z dominantą durową (dźwięk prowadzący).',
    'lab.progInfoCadence3': 'I–IV–V: kończy się na dominancie, półkadencją – dopiero kolejne przejście rozwiązuje ją do toniki.',
    'lab.progInfoAmen': 'Zwrot plagalny jak „Amen” na końcu chorału – łagodny, a nie stanowczy. Trzy akordy.',
    'lab.progInfoPlagal': 'Tonika i subdominanta na zmianę – spokojnie i hymnicznie.',
    'lab.progInfoPachelbel': 'Progresja z Kanonu Pachelbela: osiem akordów, których podstawy na przemian opadają o kwartę i wznoszą się o sekundę – nad nimi głos najwyższy schodzi krok po kroku. Także w wielu piosenkach pop.',
    'lab.progInfoCircle': 'Barokowa sekwencja ośmiu akordów: każda pryma leży kwintę niżej od poprzedniej, co nieuchronnie prowadzi do toniki.',
    'lab.progInfoJazz': 'Najważniejszy zwrot w jazzie, z akordami septymowymi – ostatni takt spoczywa na tonice.',
    'lab.progInfoTwoFiveOne': 'Ten sam zwrot w trzech akordach – i od razu od początku.',
    'lab.progInfoTurnaround': 'Jazzowa pętla na końcu chorusa: zawsze prowadzi z powrotem na początek.',
    'lab.progInfoChain': 'Cztery akordy septymowe spadające kwintami – jazzowo i ciągle w ruchu, dopiero kolejne przejście rozwiązuje.',
    'lab.progInfoModal': 'Brzmienie rockowe i folkowe ze stopniem ♭VII – tylko w skali miksolidyjskiej, doryckiej lub w molu.',
    'lab.progInfoRock3': 'Trzy akordy jak w wielu piosenkach rockowych – tylko w skali miksolidyjskiej, doryckiej lub w molu.',
    'lab.progInfoAndalusian': 'Opadająca progresja flamenco – tylko w molu, kończy się dominantą durową.',
    'lab.progInfoEpic': 'Brzmienie muzyki filmowej: wielkie, ciemne i szerokie – tylko w molu.',
    'lab.progInfoDrone': 'Jeden akord – idealny do rozśpiewania i ćwiczeń nad toniką.',
    'lab.helpSound': 'Presety to gotowe brzmienia dla melodii, arpeggiatora i klawiszy. Cztery pokrętła poniżej zmieniają najważniejsze rzeczy jednym ruchem; w „Więcej ustawień” jest każdy parametr osobno. Akordy chóru zawsze brzmią jak chór.',
    'lab.helpEffects': 'Pogłos dodaje przestrzeń, echo powtarza dźwięki w tempie, chorus poszerza brzmienie. „Udział” określa, ile syntezatora trafia do efektu; długość, sprzężenie i czas echa kształtują sam efekt.',
    'lab.helpMixer': 'Głośność każdej ścieżki: stuknij lub przeciągnij pasek. Głośnik po lewej wycisza ścieżkę. „Całość” reguluje wszystko razem.',
    'lab.helpArp': 'Arpeggiator gra dźwięki po kolei zamiast razem, w tempie groove’u. Bez „Automatycznie” grasz samodzielnie: przytrzymaj klawisze, a wzór decyduje, co z nich powstanie – „Według wyboru” gra dokładnie twoje dźwięki, „Tercje”, „Kwinty” czy „Trójdźwięki” budują na każdym dźwięku zgodnie z tonacją. Z „Trzymaj” stukasz klawisze po kolei; zostają, aż stukniesz je ponownie lub je usuniesz. Z „Automatycznie” arp podąża za progresją akordów, gdy groove gra. „Kolejność grania” gra dźwięki w kolejności naciśnięcia. Tempa z kropką (1/8 ·) biegną w poprzek taktu i brzmią jak echo; rytm „z kropką” daje skaczący shuffle.',
    'lab.helpOsc': 'Podstawowy kształt fali: sinus brzmi miękko, trójkąt jak flet, prostokąt pusto jak klarnet, piła jasno i ostro jak smyczki lub dęte.',
    'lab.helpEnv': 'Obwiednia kształtuje głośność każdego dźwięku: attack to narastanie, decay opadanie, sustain poziom podczas trzymania, release wybrzmienie po puszczeniu.',
    'lab.helpFilter': 'Filtr usuwa alikwoty: dolnoprzepustowy przyciemnia, górnoprzepustowy wyszczupla, pasmowy brzmi nosowo. Cutoff to częstotliwość graniczna, rezonans ją podkreśla, Env→Filtr otwiera filtr przy uderzeniu, przester lekko brudzi.',
    'lab.helpLfo': 'LFO to bardzo wolne drganie, które tu porusza filtrem: od lekkiego falowania po „wobble” bas. „W tempie” wiąże prędkość z tempem.',
    'lab.helpCharacter': 'Detune i szerokość pogrubiają brzmienie: kilka lekko rozstrojonych głosów rozłożonych na boki. Sub-level dodaje oktawę niżej, pitch-drop sprawia, że każdy dźwięk wjeżdża z góry.',
    'lab.helpVibrato': 'Wibrato to lekkie, regularne wahanie wysokości jak u śpiewaków. Rate to prędkość, głębokość to siła, początek to opóźnienie, zanim się zacznie.',
    'lab.helpGlide': 'Glide płynnie przesuwa wysokość z dźwięku na dźwięk zamiast skakać. Mono gra zawsze tylko jeden dźwięk, typowe dla leadów i basów.',
