    'lab.viewStudio': 'Studio',
    'lab.choirTask': 'Zadanie',
    'lab.choirHelp': 'Wybierz zadanie: ustawi groove, następstwo akordów, tempo i głosy. Wszystko można potem zmienić — i cofnąć przyciskiem ↶. W studiu są wszystkie ustawienia brzmienia, miksera i klawiszy.',
    'lab.choirPick': 'Wybierz zadanie',
    'lab.choirPickHint': 'Każde zadanie ćwiczy coś, co przydaje się na próbie chóru — z akompaniamentem do śpiewania.',
    'lab.choirPartAsk': 'Jakim głosem śpiewasz?',
    'lab.choirNow': 'Teraz',
    'lab.choirNoBeat': 'Bez rytmu',
    'lab.choirProg': 'Następstwo akordów',
    'lab.choirYou': 'ty',
    'lab.choirRoot': 'Pryma',
    'lab.choirThird': 'Tercja',
    'lab.choirSing': 'Śpiewaj',
    'lab.choirListen': 'Słuchaj',
    'lab.choirYouSing': 'Ty',
    'lab.choirClap24': 'Klaskanie na 2 i 4',
    'lab.choirBeatFade': 'Wycisz rytm',
    'lab.choirBeatBack': 'Przywróć rytm',
    'lab.melodyAltBars': 'Melodia co drugi takt (echo)',
    'lab.task.meineStimme.title': 'Śpiewaj swój głos',
    'lab.task.meineStimme.help1': 'Brzmi czterogłos, twój głos jest wyróżniony. Śpiewaj z nim — najpierw razem, potem spróbuj utrzymać go samodzielnie.',
    'lab.task.meineStimme.help2': 'Wskazówka: zacznij wolno, potem przyspiesz.',
    'lab.task.minusEins.title': 'Brakuje twojego głosu',
    'lab.task.minusEins.help1': 'Brzmią trzy pozostałe głosy, twój jest wyciszony. Wypełnij lukę.',
    'lab.task.minusEins.help2': 'Gdy poczujesz niepewność: przełącz na chwilę na „Śpiewaj swój głos” i wróć.',
    'lab.task.bass.title': 'Śpiewaj prymy',
    'lab.task.bass.help1': 'Śpiewaj prymę każdego akordu — to fundament, na którym stroi chór.',
    'lab.task.bass.help2': 'Niskie głosy w swojej skali, wysokie oktawę wyżej.',
    'lab.task.terzen.title': 'Śpiewaj tercję',
    'lab.task.terzen.help1': 'Śpiewaj tercję każdego akordu. Ekran ją podpowiada.',
    'lab.task.terzen.help2': 'Tercja decyduje o dur i moll — i w chórze najłatwiej ją zaniżyć.',
    'lab.task.liegeton.title': 'Gama na burdonie',
    'lab.task.liegeton.help1': 'Brzmi tylko pryma z kwintą. Śpiewaj powoli gamę w górę i w dół i słuchaj, jak każdy dźwięk brzmi z burdonem.',
    'lab.task.liegeton.help2': 'Uważnie przy 3 i 7: tercję wielką raczej wąsko, dźwięk prowadzący dość wysoko.',
    'lab.task.pentatonik.title': 'Improwizacja na pięciu dźwiękach',
    'lab.task.pentatonik.help1': 'Wymyślaj krótkie melodie tylko z pięciu pokazanych dźwięków — z nimi nic nie zabrzmi źle.',
    'lab.task.pentatonik.help2': 'Najpierw jeden dźwięk, potem dwa, potem małe motywy. Pauzy są dozwolone i dobre.',
    'lab.task.echo.title': 'Echo',
    'lab.task.echo.help1': 'Aplikacja śpiewa jeden takt, w następnym ty go powtarzasz.',
    'lab.task.echo.help2': 'Najpierw powtarzaj dokładnie, potem lekko zmieniaj — tak powstaje pytanie i odpowiedź.',
    'lab.task.zweiVier.title': 'Klaskanie na 2 i 4',
    'lab.task.zweiVier.help1': 'Jak w gospel: klaszcz na 2 i 4, stopą na 1 i 3.',
    'lab.task.zweiVier.help2': 'Ekran miga na 2 i 4. Najpierw na siedząco, potem na stojąco z krokiem w bok.',
    'lab.task.swing.title': 'Ósemki swingowe',
    'lab.task.swing.help1': 'Mów do rytmu „du-ba du-ba”: „du” długo, „ba” krótko i później — jak „długo-krótko”.',
    'lab.task.swing.help2': 'Potem zaśpiewaj ten sam ruch ósemkowy na jednym dźwięku.',
    'lab.task.beatbox.title': 'Beatbox',
    'lab.task.beatbox.help1': 'Rób rytm ustami: „bm” to stopa, „ka” to werbel, „ts” to hi-hat.',
    'lab.task.beatbox.help2': 'Gdy już siedzi: „Wycisz rytm” — wtedy samodzielnie niesiesz groove.',
    // Groove Lab: warsztat
